import{_ as a,o as d,c as e,a2 as r}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"衡元宙（ヘン・ユアンジョウ）宇宙総覧","description":"","frontmatter":{},"headers":[],"relativePath":"ja/00-衡元宙宇宙总览.md","filePath":"ja/00-衡元宙宇宙总览.md","lastUpdated":1789183869000}'),l={name:"ja/00-衡元宙宇宙总览.md"};function o(i,t,h,n,s,p){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="衡元宙-ヘン・ユアンジョウ-宇宙総覧" tabindex="-1">衡元宙（ヘン・ユアンジョウ）宇宙総覧 <a class="header-anchor" href="#衡元宙-ヘン・ユアンジョウ-宇宙総覧" aria-label="Permalink to &quot;衡元宙（ヘン・ユアンジョウ）宇宙総覧&quot;">​</a></h1><table tabindex="0"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td>文書番号</td><td>00</td></tr><tr><td>モジュール</td><td>総綱と核心設定</td></tr><tr><td>キーワード</td><td>衡元宙、錨点、共生、万族、本源</td></tr></tbody></table><h2 id="第一節-宇宙の基本定義" tabindex="-1">第一節 宇宙の基本定義 <a class="header-anchor" href="#第一節-宇宙の基本定義" aria-label="Permalink to &quot;第一節 宇宙の基本定義&quot;">​</a></h2><p>万霊衡锚本源宙（以下「衡元宙」と略称）は、錨点共生文明が居住し統治する宇宙の全域である。衡元宙は単一の物理的空間ではなく、物質位面、エネルギー層、意識域、法則網が共同で構成する複合的存在体である。その名称のうち「万霊」は知覚と進化の潜在能力を備えたすべての生命形態を指し、「衡锚」は宇宙の平衡を維持する錨点機構を指し、「本源宙」はこの宇宙が本源法則を根基とし、共生進化を方向とする本質的属性を強調するものである。</p><p>衡元宙の核心的特徴はその「進化可能性」にある。伝統的な略奪式宇宙観が宇宙を有限な資源の狩場と見なすのとは異なり、衡元宙は宇宙自体が生命体であり、そのエントロピー増大の過程は秩序ある共生網を通じて逆転・調整できると考える。錨点機構はまさにこの調整の核心的手段である——宇宙の重要な節点に安定した錨点を確立することで、分散した個体エネルギーを秩序ある進化の奔流に集約し、最終的に宇宙全体の昇維（次元上昇）を実現する。</p><h2 id="第二節-宇宙の構造階層" tabindex="-1">第二節 宇宙の構造階層 <a class="header-anchor" href="#第二節-宇宙の構造階層" aria-label="Permalink to &quot;第二節 宇宙の構造階層&quot;">​</a></h2><p>衡元宙は構造的に四つの階層に分かれており、各階層は隔絶しているのではなく、錨点網を通じて相互に連通している：</p><table tabindex="0"><thead><tr><th>階層</th><th>名称</th><th>特徴</th><th>主な居住者</th></tr></thead><tbody><tr><td>第一層</td><td>物質位面</td><td>物理法則に従う実体世界、無数の惑星と銀河を含む</td><td>人族及び多数の物質生命</td></tr><tr><td>第二層</td><td>エネルギー層</td><td>高濃度エネルギーの集積領域、法則が半顕性を呈する</td><td>エネルギー生命、修練者の霊体</td></tr><tr><td>第三層</td><td>意識域</td><td>集団意識と個体意識が交わる情報空間</td><td>意識体、高次元存在</td></tr><tr><td>第四層</td><td>法則網</td><td>宇宙本源法則の運行底層、錨点の根基層</td><td>錨点自体、宇宙意志</td></tr></tbody></table><p>四つの階層のエネルギーと情報の流れは「下渗上匯（下方浸透・上方集約）」の原則に従う：下層の修練成果は上方に向かって法則網に集約され、法則網の安定したフィードバックは下方に向かって各層の生命を滋養する。錨点は階層を跨ぐ接続ハブとして、この流れが略奪行為によって寸断されないことを確保する。</p><h2 id="第三節-宇宙の核心的矛盾" tabindex="-1">第三節 宇宙の核心的矛盾 <a class="header-anchor" href="#第三節-宇宙の核心的矛盾" aria-label="Permalink to &quot;第三節 宇宙の核心的矛盾&quot;">​</a></h2><p>衡元宙の根本的矛盾は「略奪と共生」の矛盾である。錨点機構が全面的に確立される前、宇宙には長期にわたり略奪式修練体系が存在した——強者は弱者のエネルギー、気運、さらには本源を吞噬することで自身の進化を実現し、宇宙全体のエントロピー増大を加速させ、文明の断層を頻発させた。この体系は短期的には個別の強者を生み出す可能性があるが、長期的には宇宙の進化潜在能力を枯渇させる。</p><p>錨点共生文明の誕生はまさにこの矛盾への応答である。三百套の宇宙本源修練体系を開放し、聯産承包機制（生産連動請負機制）を確立し、20%の衆生を位面至高強者として活性化することで、共生文明は進化が他者の犠牲を代償とする必要がなく、集団の秩序ある進化が個体の略奪式跳躍をはるかに凌駕することを証明しようとする。</p><h2 id="第四節-宇宙の発展方向" tabindex="-1">第四節 宇宙の発展方向 <a class="header-anchor" href="#第四節-宇宙の発展方向" aria-label="Permalink to &quot;第四節 宇宙の発展方向&quot;">​</a></h2><p>衡元宙の究極的方向は「万族共生、宇宙昇維」である。この方向は四階段の経路を通じて段階的に実現される：</p><ol><li><strong>現実築基</strong>：物質位面に共生社会制度を確立し、略奪の根源を除去する</li><li><strong>科技賦能</strong>：修練法則と技術工学を結合し、進化の門戸を引き下げる</li><li><strong>意識進化</strong>：生命形態が意識域へ移行することを推進し、精神層面の共生を実現する</li><li><strong>星際共生</strong>：位面を跨ぎ、星間を跨いで完全な錨点網を構築し、宇宙全体の昇維を完成させる</li></ol><p>現在、衡元宙は第一階段から第二階段への移行の重要な時期にあり、錨点共生文明の各種制度が全面的に落地しつつある。</p><h2 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to &quot;結語&quot;">​</a></h2><p>衡元宙は静的な宇宙ではなく、進化中の生命共同体である。衡元宙を理解することは、共生進化の可能性を理解することである。本総覧は全文書の起点として、後続の各モジュールは法則、機構、社会、法律、生命、技術、歴史、位面間などの次元から詳述を展開する。</p><h2 id="関連文書" tabindex="-1">関連文書 <a class="header-anchor" href="#関連文書" aria-label="Permalink to &quot;関連文書&quot;">​</a></h2><ul><li>01-锚点共生文明宣言 (錨点共生文明宣言)</li><li>03-共生文明宪章 (共生文明憲章)</li><li>10-三百套本源修炼体系总览 (三百套本源修練体系総覧)</li></ul>',20)])])}const b=a(l,[["render",o]]);export{c as __pageData,b as default};
